export function joystick(canvas){const state={x:0,y:0,dragged:false};let pointer=null,start;const ring=document.createElement('div');ring.className='touch-stick';ring.innerHTML='<i></i>';document.body.append(ring);const reset=()=>{pointer=null;state.x=state.y=0;ring.hidden=true;};reset();canvas.addEventListener('pointerdown',e=>{if(document.querySelector('dialog[open]')||pointer!==null)return;pointer=e.pointerId;start={x:e.clientX,y:e.clientY};state.dragged=false;ring.style.left=start.x+'px';ring.style.top=start.y+'px';canvas.setPointerCapture(pointer);});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer)return;const dx=e.clientX-start.x,dy=e.clientY-start.y,d=Math.hypot(dx,dy);if(d>9)state.dragged=true;if(!state.dragged)return;ring.hidden=false;const n=Math.max(50,d);state.x=dx/n;state.y=dy/n;ring.firstChild.style.transform=`translate(${state.x*35}px,${state.y*35}px)`;});canvas.addEventListener('pointerup',reset);canvas.addEventListener('pointercancel',reset);window.addEventListener('blur',reset);document.addEventListener('visibilitychange',reset);return state;}
